<?php
require_once __DIR__.'/../includes/authorization.php';require_role('seller');require_once __DIR__.'/../includes/Repositories/OrderRepository.php';
$repo=new OrderRepository();$sellerId=(int)$_SESSION['user_id'];$errors=[];$transitions=['requested'=>['accepted','cancelled'],'accepted'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[]];
if(is_post()){
 if(!verify_csrf()){flash('error','Sesi formulir tidak valid.');redirect(page_url('seller-orders'));}$orderId=filter_input(INPUT_POST,'order_id',FILTER_VALIDATE_INT);$new=$_POST['status']??'';
 $items=$orderId?$repo->sellerOrderItems((int)$orderId,$sellerId):[];$stmt=$orderId?db()->prepare('SELECT status FROM orders WHERE id=? LIMIT 1'):null;if($stmt)$stmt->execute([$orderId]);$current=$stmt?$stmt->fetchColumn():false;
 if(!$orderId||!$items||!isset($transitions[$current])||!in_array($new,$transitions[$current],true))$errors[]='Perubahan status tidak valid atau pesanan bukan milik produkmu.';else{$repo->setStatusSeller((int)$orderId,$sellerId,$new);flash('success','Status pesanan diperbarui.');redirect(page_url('seller-orders'));}
}
